BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='120s';
CREATE SCHEMA IF NOT EXISTS private;
ALTER TABLE public.products ADD COLUMN catalog_archived_at timestamptz,ADD COLUMN catalog_archive_reason text;
ALTER TABLE public.products ADD CONSTRAINT products_catalog_archive_pair CHECK((catalog_archived_at IS NULL)=(catalog_archive_reason IS NULL));
ALTER TABLE public.products ADD CONSTRAINT products_archived_not_visible CHECK(catalog_archived_at IS NULL OR is_visible IS FALSE);
CREATE INDEX products_catalog_archive ON public.products(catalog_archived_at) WHERE catalog_archived_at IS NOT NULL;
CREATE TABLE private.catalog_record_archive(
 product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE RESTRICT,
 category text NOT NULL CHECK(category IN('historical_synthetic','manufacturer_directory_not_sku')),
 reason text NOT NULL,before_product jsonb NOT NULL,before_queue jsonb,related_evidence jsonb NOT NULL,
 archived_at timestamptz NOT NULL DEFAULT now()
);
REVOKE ALL ON private.catalog_record_archive FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE private.catalog_record_archive IS 'User-authorized 2026-11-13 archival of 800 historical synthetic records and 173 manufacturer-directory entries. Original rows, IDs, relationships, missing fields and independent audit history are preserved. Archival is not evidence completion.';
