  SELECT * INTO p FROM public.products WHERE id=(r->>'id')::uuid FOR UPDATE;
  IF NOT FOUND THEN CONTINUE; END IF;
  IF p.name IS DISTINCT FROM r->>'name' OR p.brand_name IS DISTINCT FROM r->>'brand' OR p.created_at IS DISTINCT FROM(r->>'created_at')::timestamptz OR p.catalog_source_url IS NOT NULL OR p.is_visible IS DISTINCT FROM false THEN RAISE EXCEPTION 'Archival candidate changed: %',r->>'id'; END IF;
  reason:=CASE r->>'category' WHEN 'historical_synthetic' THEN '과거 무작위 가상 상품 생성 기록. generate_mock_products.py (commit 8e900c9)의 브랜드·이름·중량·이미지·생성 배치와 일치합니다. 실재 제품으로 확정할 수 없어 사용자 승인으로 원본 보관합니다.' ELSE '인천 공개 사료 제조업체 명단을 제품으로 가져온 기록. 업체명·업종·목록 번호는 소비자용 제품 배합을 식별하지 못하므로 사용자 승인으로 원본 보관합니다.' END;
  INSERT INTO private.catalog_record_archive(product_id,category,reason,before_product,before_queue,related_evidence)
   SELECT p.id,r->>'category',reason,to_jsonb(p),(SELECT to_jsonb(q)FROM public.product_enrichment_queue q WHERE q.product_id=p.id),jsonb_build_object(
    'ingredient_links',(SELECT COALESCE(jsonb_agg(i),'[]')FROM public.product_ingredients i WHERE i.product_id=p.id),
    'nutrition',(SELECT COALESCE(jsonb_agg(n),'[]')FROM public.nutritional_profiles n WHERE n.product_id=p.id),
    'observations',(SELECT COALESCE(jsonb_agg(o),'[]')FROM public.product_observations o WHERE o.product_id=p.id),
    'barcodes',(SELECT COALESCE(jsonb_agg(b),'[]')FROM public.product_barcodes b WHERE b.product_id=p.id),
    'sources',(SELECT COALESCE(jsonb_agg(s),'[]')FROM public.product_data_sources s WHERE s.product_id=p.id),
    'label_sets',(SELECT COALESCE(jsonb_agg(s),'[]')FROM public.product_ingredient_label_sets s WHERE s.product_id=p.id));
  UPDATE public.products SET catalog_archived_at=now(),catalog_archive_reason=reason WHERE id=p.id;
 END LOOP;
END $archive$;
NOTIFY pgrst,'reload schema';
COMMIT;
